export const isWordChar = (c: string): boolean => /[a-zA-Z]/.test(c);
===== rules-builder/parse-char.ts =====
import { GrammarParseError, } from "../utils/errors/grammar-parse-error.js";

export const parseChar = (src: string, pos: number): [number, number] => {
  if (src[pos] === '\\') {
    // if (src.slice(pos, pos + 1) === '\\') {
    switch (src[pos + 1]) {
      case 'x': return [parseInt(src.slice(pos + 2, pos + 4), 16), 4,];
      case 'u': return [parseInt(src.slice(pos + 2, pos + 6), 16), 6,];
      case 'U': return [parseInt(src.slice(pos + 2, pos + 10), 16), 10,];
      case 't': return ['\t'.charCodeAt(0), 2,];
      case 'r': return ['\r'.charCodeAt(0), 2,];
      case 'n': return ['\n'.charCodeAt(0), 2,];

      case '"':
      case '[':
      case ']':
        return [src.charCodeAt(pos + 1), 2,];
      case '\\':
        const codePoint = src.codePointAt(pos + 1);
        if (codePoint === undefined) {
          throw new GrammarParseError(src, pos, "Could not get code point for character");
        }
        return [codePoint, 2,];
      default:
        throw new GrammarParseError(src, pos, `Unknown escape at ${src[pos]}`);
    }
  }

  if (!src[pos]) {
    throw new GrammarParseError(src, pos, "Unexpected end of grammar input, failed to complete parse");
  }
  return [src.charCodeAt(pos), 1,];
};
===== rules-builder/parse-name.ts =====
import { GrammarParseError, } from "../utils/errors/grammar-parse-error.js";

export const PARSE_NAME_ERROR = 'Failed to find a valid name';
export const GET_INVALID_CHAR_ERROR = (char: string) => `Invalid character "${char}" when parsing name, only lowercase letters and hyphens are allowed.`;

const isValidChar = (char: string) => /[a-zA-Z-]/.test(char);
const isInvalidNextChar = (char: string) => /[_0-9]/.test(char);

export const parseName = (grammar: string, pos: number): string => {
  let name = '';
  while (pos < grammar.length && (isValidChar(grammar[pos]))) {
    name += grammar[pos];
    pos++;
  }
  if (!name) {
    throw new GrammarParseError(grammar, pos, PARSE_NAME_ERROR);
  }
  if (pos < grammar.length && isInvalidNextChar(grammar[pos])) {
    throw new GrammarParseError(grammar, pos, GET_INVALID_CHAR_ERROR(grammar[pos]));
  }
  return name;
};
===== rules-builder/parse-space.ts =====
export const parseSpace = (src: string, pos: number, newline_ok: boolean): number => {
  while (src[pos] === ' ' || src[pos] === '\t' || src[pos] === '#' ||
    (newline_ok && (src[pos] === '\r' || src[pos] === '\n'))) {
    if (src[pos] === '#') {
      while (src[pos] && src[pos] !== '\r' && src[pos] !== '\n') {
        pos++;
      }
    } else {
      pos++;
    }
  }
  return pos;
};
