export enum InternalRuleType {
  CHAR = 'CHAR',
  CHAR_RNG_UPPER = 'CHAR_RNG_UPPER',
  // CHAR_RNG = 'CHAR_RNG',
  RULE_REF = 'RULE_REF',
  ALT = 'ALT',
  END = 'END',

  CHAR_NOT = 'CHAR_NOT',
  CHAR_ALT = 'CHAR_ALT',
}

export interface InternalRuleDefWithNumericValue {
  type: InternalRuleType.RULE_REF | InternalRuleType.CHAR_ALT | InternalRuleType.CHAR_RNG_UPPER;
  value: number;
}
