    this.#keys.delete(key);
    this.#set.delete(ref);
  };

  has = (el: T) => this.#set.has(el);
  get = (el: T) => this.#keys.get(this.getKey(el));

  *[Symbol.iterator](): IterableIterator<T> {
    yield* this.#set;
  }

  get size() { return this.#set.size; }
}
