export class GraphPointer<R extends UnresolvedRule = UnresolvedRule> {
  node: GraphNode<R>;
  parent?: GraphPointer;
  #valid?: boolean;
  id: string;

  constructor(node: GraphNode<R>, parent?: GraphPointer) {
    if (node === undefined) {
      throw new Error('Node is undefined');
