        if (!this.node.next) {
          throw new Error(`No next node: ${JSON.stringify(this.node)}`);
        }
        yield* new GraphPointer(this.node.next, this.parent).resolve();
      } else {

        for (const node of this.node.rule.nodes) {
          yield* new GraphPointer(node, this).resolve();
        }
