import { readFileSync } from 'node:fs';
import { GBNF } from '/tmp/ref/gbnf.ts';

const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));

const err = (e) => ({
  error: e.constructor.name === 'GrammarParseError' || e.constructor.name === 'InputParseError'
    ? e.constructor.name : 'Error',
  message: e.message,
});

const results = cases.map(({ grammar, inputs }) => {
  const steps = [];
  let state;
  try {
    state = GBNF(grammar);
  } catch (e) {
    return { init: err(e), steps };
  }
  const snapshot = (s) => ({ rules: [...s].map(r => ({ type: r.type, value: r.value ?? null })), size: s.size });
  steps.push(snapshot(state));
  for (const input of inputs) {
    try {
      state = state.add(input);
      steps.push(snapshot(state));
    } catch (e) {
      steps.push(err(e));
      break;
    }
  }
  return { init: null, steps, print: state ? state._graph.print({ colors: false }) : null };
});

console.log(JSON.stringify(results, null, 2));

