import json
import random
import string

random.seed(20260909)

ATOMS = [
    '"a"', '"ab"', '"abc"', '"\\n"', '"\\t"', '"\\x41"', '"\\u00e9"', '"\\""',
    '[a-z]', '[A-Z]', '[0-9]', '[abc]', '[^a-z]', '[^0-9]', '[a-zA-Z0-9_]', '[\\]]', '[a-]',
    '""', '[ \\t\\n]',
]
SUFFIXES = ['', '', '', '*', '+', '?']


def gen_seq(depth, names):
    parts = []
    for _ in range(random.randint(1, 3)):
        roll = random.random()
        if roll < 0.55 or depth > 2:
            part = random.choice(ATOMS)
        elif roll < 0.8:
            part = '(' + gen_alts(depth + 1, names) + ')'
        else:
            part = random.choice(names) if names else random.choice(ATOMS)
        parts.append(part + random.choice(SUFFIXES))
    return ' '.join(parts)


def gen_alts(depth, names):
    return ' | '.join(gen_seq(depth, names) for _ in range(random.randint(1, 3)))


def gen_grammar():
    n = random.randint(0, 3)
    names = [f'rule-{i}' for i in range(n)]
    lines = []
    for i, name in enumerate(names):
        lines.append(f'{name} ::= {gen_alts(0, names[i + 1:])}')
    lines.insert(0, f'root ::= {gen_alts(0, names)}')
    if random.random() < 0.2:
        lines.insert(random.randrange(len(lines) + 1), '# a comment')
    grammar = '\n'.join(lines)
    if random.random() < 0.5:
        grammar += '\n'
    if random.random() < 0.15:
        # random mutation, often producing an invalid grammar
        pos = random.randrange(len(grammar))
        grammar = grammar[:pos] + random.choice('|()[]*+?":=\\ \n#-') + grammar[pos + 1:]
    return grammar


ALPHABET = string.ascii_letters + string.digits + ' \t\n"[]()\\-.,{}éA'


def gen_inputs():
    inputs = []
    for _ in range(random.randint(1, 4)):
        roll = random.random()
        if roll < 0.75:
            inputs.append(''.join(random.choice(ALPHABET) for _ in range(random.randint(1, 4))))
        elif roll < 0.9:
            inputs.append(ord(random.choice(ALPHABET)))
        else:
            inputs.append([ord(random.choice(ALPHABET)) for _ in range(random.randint(1, 3))])
    return inputs


cases = []
for _ in range(2000):
    case = {'grammar': gen_grammar(), 'inputs': gen_inputs()}
    if random.random() < 0.2:
        case['initial'] = ''.join(random.choice(ALPHABET) for _ in range(random.randint(0, 3)))
    cases.append(case)

with open('/tmp/fuzz_cases.json', 'w') as f:
    json.dump(cases, f)
print(len(cases), 'cases')

