            else:
                if not pointer.node.next:
                    raise RuntimeError(f'No next node: {pointer.node!r}')
                yield from GraphPointer(pointer.node.next, pointer.parent).resolve()
                return

    @property
    def rule(self) -> Any:
        return self.node.rule

    @property
    def valid(self) -> bool | None:
        return self._valid

    @valid.setter
